#include <random>
#include <stdexcept>
#include <utility>
#include <vector>

std::pair<int, int> partition3(std::vector<int>& a, int lo, int hi, int pivot)
{
    int lt = lo, i = lo, gt = hi;
    while (i <= gt)
    {
        if (a[i] < pivot) std::swap(a[lt++], a[i++]);
        else if (pivot < a[i]) std::swap(a[i], a[gt--]);
        else ++i;
    }
    return { lt, gt };
}

static std::mt19937& rng()
{
    static std::mt19937 engine(12345);
    return engine;
}

static int randomIn(int lo, int hi) { return std::uniform_int_distribution<int>(lo, hi)(rng()); }

void quickSort(std::vector<int>& a)
{
    int lo = 0, hi = static_cast<int>(a.size()) - 1;
    std::vector<std::pair<int, int>> pending;          // an explicit stack instead of recursion
    while (true)
    {
        while (lo < hi)
        {
            auto [lt, gt] = partition3(a, lo, hi, a[randomIn(lo, hi)]);
            if (lt - lo < hi - gt) { pending.push_back({ gt + 1, hi }); hi = lt - 1; }   // do the smaller side now
            else { pending.push_back({ lo, lt - 1 }); lo = gt + 1; }
        }
        if (pending.empty()) return;
        std::tie(lo, hi) = pending.back();
        pending.pop_back();
    }
}

int kthSmallest(std::vector<int> a, int k)
{
    if (k < 0 || k >= static_cast<int>(a.size())) throw std::out_of_range("k");
    int lo = 0, hi = static_cast<int>(a.size()) - 1;
    while (true)
    {
        auto [lt, gt] = partition3(a, lo, hi, a[randomIn(lo, hi)]);
        if (k < lt) hi = lt - 1;
        else if (k > gt) lo = gt + 1;
        else return a[k];
    }
}

