#include <algorithm>

static bool sortedAsc(const std::vector<int>& a) { for (std::size_t i = 1; i < a.size(); ++i) if (a[i] < a[i - 1]) return false; return true; }

TEST("three-way partition") {
    std::vector<int> a{ 2, 0, 1, 2, 1, 0, 0, 2, 1 };
    auto [lt, gt] = partition3(a, 0, 8, 1);
    CHECK_EQ(lt, 3);
    CHECK_EQ(gt, 5);
    CHECK_EQ(a, (std::vector<int>{ 0, 0, 0, 1, 1, 1, 2, 2, 2 }));
    std::vector<int> b{ 9, 5, 7, 1, 3 };
    auto [l2, g2] = partition3(b, 1, 3, 4);                  // only b[1..3] = 5, 7, 1
    CHECK_EQ(b[0], 9);
    CHECK_EQ(b[4], 3);
    CHECK_EQ(b[1], 1);
    CHECK_EQ(l2, 2);
    CHECK_EQ(g2, 1);
}
TEST("sorting small inputs") {
    std::vector<int> a{ 10, 80, 30, 90, 40, 50, 70, -5, 30 };
    quickSort(a);
    CHECK_EQ(a, (std::vector<int>{ -5, 10, 30, 30, 40, 50, 70, 80, 90 }));
    std::vector<int> e;
    quickSort(e);
    CHECK(e.empty());
    std::vector<int> one{ 4 };
    quickSort(one);
    CHECK_EQ(one, (std::vector<int>{ 4 }));
}
TEST("100,000 sorted, reversed and random values") {
    std::vector<int> s(100000), r(100000), x(100000);
    for (int i = 0; i < 100000; ++i) { s[i] = i; r[i] = 100000 - i; x[i] = (i * 7919) % 65537 - 30000; }
    quickSort(s); quickSort(r); quickSort(x);
    CHECK(sortedAsc(s));
    CHECK(sortedAsc(r));
    CHECK(sortedAsc(x));
    CHECK_EQ(r.front(), 1);
}
TEST("100,000 equal values and a few distinct ones") {
    std::vector<int> same(100000, 7);
    quickSort(same);
    CHECK(sortedAsc(same));
    std::vector<int> few(100000);
    for (int i = 0; i < 100000; ++i) few[i] = i % 3;
    quickSort(few);
    CHECK(sortedAsc(few));
    CHECK_EQ(few[33334], 1);
}
TEST("k-th smallest") {
    std::vector<int> a{ 9, 1, 8, 2, 7, 3, 6, 4, 5 };
    CHECK_EQ(kthSmallest(a, 0), 1);
    CHECK_EQ(kthSmallest(a, 4), 5);
    CHECK_EQ(kthSmallest(a, 8), 9);
    CHECK_EQ(kthSmallest({ 5, 5, 5, 1 }, 2), 5);
    CHECK_THROWS(kthSmallest(a, 9));
    CHECK_THROWS(kthSmallest({}, 0));
    std::vector<int> big(100000);
    for (int i = 0; i < 100000; ++i) big[i] = 100000 - i;
    CHECK_EQ(kthSmallest(big, 49999), 50000);
    std::vector<int> equal(100000, 3);
    CHECK_EQ(kthSmallest(equal, 777), 3);
}

